import { readFile, writeFile } from 'node:fs/promises'
import { parseArgs } from 'node:util'
import { z } from 'zod'
import { parseAuditInput } from './cli'
import { fingerprint } from './evidence'
import { buildJanitorReport } from './report'
import { runSemanticPilot, semanticClusters, semanticReplySchema, type SemanticOptions } from './semantic'

// Labels are operator adjudications recorded before inference, never generated by the model.
export const reviewSampleSchema = z.object({
  recordedAt: z.string().datetime(), snapshotAt: z.string().datetime(),
  notes: z.string().min(1),
  cases: z.array(z.object({ clusterId: z.string(), expected: z.array(semanticReplySchema.shape.classification).min(1),
    group: z.enum(['duplicate', 'overlap', 'sibling', 'independent', 'historical', 'stale-active']), rationale: z.string().min(1) }).strict()).min(25).max(40),
}).strict()
export type ReviewSample = z.infer<typeof reviewSampleSchema>

export async function evaluateJanitorSample(inputValue: unknown, sampleValue: unknown, options: SemanticOptions = {}, fetcher: typeof fetch = fetch) {
  const input = parseAuditInput(inputValue), sample = reviewSampleSchema.parse(sampleValue)
  if (sample.snapshotAt !== input.snapshot.generatedAt) throw new Error('Sample labels must refer to this saved source snapshot')
  if (new Set(sample.cases.map(c => c.clusterId)).size !== sample.cases.length) throw new Error('Sample cases must name unique candidate clusters')
  if (Date.parse(sample.recordedAt) > Date.now()) throw new Error('Record expected labels before running the model')
  const candidates = semanticClusters(buildJanitorReport(input), input)
  const clusters = sample.cases.map(c => {
    const cluster = candidates.find(cluster => cluster.id === c.clusterId)
    if (!cluster) throw new Error('Sample cluster is absent from the deterministic source report')
    return cluster
  })
  const result = await runSemanticPilot(clusters, options, fetcher)
  const cases = sample.cases.map((c, index) => {
    const proposal = result.proposals[index]!
    const label = proposal.reply?.classification ?? 'abstain'
    const expected = c.expected.includes(label)
    const suggestion = !['abstain', 'independent'].includes(label)
    return { ...c, pages: proposal.pages, actual: label, expectedMatch: expected,
      falsePositive: suggestion && !expected, outcome: proposal.outcome, reason: proposal.abstainReason ?? proposal.reply?.reason,
      cacheHit: proposal.cacheHit, latencyMs: result.metrics.calls.find(call => call.clusterId === c.clusterId)?.latencyMs ?? null }
  })
  const calls = result.metrics.calls
  const latencies = calls.map(c => c.latencyMs).sort((a, b) => a - b)
  const negativeCases = cases.filter(c => !c.expected.some(label => ['possible_duplicate', 'possible_superseded', 'overlapping_scope', 'stale_needs_owner_update'].includes(label))).length
  const falsePositives = cases.filter(c => c.falsePositive).length
  const negativeFalsePositives = cases.filter(c => c.falsePositive && !c.expected.some(label => !['independent', 'abstain'].includes(label))).length
  return { schema: 'tinstar.janitor-pilot-evaluation.v1', evaluatedAt: new Date().toISOString(), snapshotAt: sample.snapshotAt,
    sampleRecordedAt: sample.recordedAt, sampleFingerprint: fingerprint(sample), sourceFingerprint: fingerprint(input),
    notes: sample.notes, cases, metrics: { ...result.metrics, sampleSize: cases.length, negativeCases, falsePositives,
      negativeFalsePositives, falsePositiveRate: negativeCases ? negativeFalsePositives / negativeCases : null,
      abstainRate: result.metrics.abstentions / cases.length,
      modelAbstainRate: calls.length ? cases.filter(c => c.actual === 'abstain' && c.outcome === 'classified' && !c.cacheHit).length / calls.length : null,
      schemaRejectRate: calls.length ? result.metrics.schemaRejects / calls.length : null,
      referenceRejectRate: calls.length ? result.metrics.referenceRejects / calls.length : null,
      expectedMatches: cases.filter(c => c.expectedMatch).length,
      latencyMs: { min: latencies[0] ?? null, median: latencies[Math.floor(latencies.length / 2)] ?? null, max: latencies.at(-1) ?? null },
      inferenceSeconds: calls.some(c => c.gpuSeconds !== null) ? calls.reduce((sum, c) => sum + (c.gpuSeconds ?? 0), 0) : null,
      inferenceTimeBasis: 'Ollama prompt_eval_duration + eval_duration; GPU-backed inference duration, not exclusive device occupancy or billing',
      inferenceCost: 'local GPU; no paid API' }, warnings: result.warnings, semantic: result }
}

export async function runJanitorPilotCli(args: string[]) {
  const { values } = parseArgs({ args, options: { input: { type: 'string' }, sample: { type: 'string' }, output: { type: 'string' },
    endpoint: { type: 'string' }, model: { type: 'string' }, 'max-calls': { type: 'string' }, 'max-tokens': { type: 'string' },
    'max-time-ms': { type: 'string' }, 'timeout-ms': { type: 'string' }, 'busy-file': { type: 'string' }, help: { type: 'boolean' } } })
  if (values.help) {
    process.stdout.write('Usage: npm run --silent janitor:pilot -- --input SAVED_AUDIT_INPUT --sample LABELS_JSON --output RESULTS_JSON [--endpoint PRIVATE_OLLAMA_ORIGIN] [--model NAME] [--max-calls N] [--max-tokens N] [--max-time-ms N] [--timeout-ms N] [--busy-file FILE]\nRequires 25-40 unique, prelabelled slice A clusters. Uses the same defaults and private cache as janitor:report --semantic. Explicitly increase the default 4-call/32000-token/120000-ms budget for a full pilot. No automatic inference on import, hosted fallback or Notion write.\n')
    return
  }
  if (!values.input || !values.sample || !values.output) throw new Error('Provide saved input, pre-recorded sample labels and private results file (see --help)')
  const number = (s?: string) => s === undefined ? undefined : Number(s)
  const result = await evaluateJanitorSample(JSON.parse(await readFile(values.input, 'utf8')), JSON.parse(await readFile(values.sample, 'utf8')), {
    endpoint: values.endpoint, model: values.model, maxCalls: number(values['max-calls']), maxTokens: number(values['max-tokens']),
    maxRunMs: number(values['max-time-ms']), timeoutMs: number(values['timeout-ms']), busyFile: values['busy-file'],
  })
  await writeFile(values.output, JSON.stringify(result, null, 2) + '\n', { mode: 0o600 })
  process.stdout.write(JSON.stringify({ metrics: result.metrics, warnings: result.warnings }) + '\n')
}
